<div class="grid gap-5 xl:grid-cols-[420px_minmax(0,1fr)]"><form method="POST" action="{{ route('purchases.returns.store') }}" class="panel h-fit space-y-4" id="return-form">@csrf<x-submission-token/><h2 class="text-lg font-extrabold">＋ New Purchase Return</h2><label><span class="label">Purchase Invoice *</span><select name="purchase_id" class="field" required data-purchase><option value="">Select purchase</option>@foreach($purchases as $purchase)<option value="{{ $purchase->id }}" @selected(request('purchase')==$purchase->id)>{{ $purchase->invoice_number }} — {{ $purchase->supplier->name }}</option>@endforeach</select></label><div class="grid gap-3 sm:grid-cols-2"><div class="rounded-xl bg-slate-50 p-3"><small class="text-slate-400">Supplier</small><b class="block" data-supplier>—</b></div><div class="rounded-xl bg-slate-50 p-3"><small class="text-slate-400">Store</small><b class="block" data-store>—</b></div></div><label><span class="label">Product Item *</span><select name="purchase_item_id" class="field" required data-item><option value="">Select product from purchase</option></select></label><label><span class="label">Return Quantity *</span><input type="number" step="any" min=".01" name="quantity" class="field" required></label><label><span class="label">Return Reason *</span><input name="reason" class="field" placeholder="Damaged / incorrect / excess" required></label><label><span class="label">Refund Type *</span><select name="refund_type" class="field" required data-refund><option>Supplier credit</option><option>Cash refund</option><option>Replacement</option></select></label><label data-account class="hidden"><span class="label">Refund To Account *</span><select name="account_id" class="field"><option value="">Select account</option>@foreach($accounts as $account)<option value="{{ $account->id }}" @selected($account->code === 'MAIN' || $account->type === 'main')>{{ $account->name }}</option>@endforeach</select></label><label><span class="label">Return Date