<div class="space-y-4"><form class="panel grid gap-3 sm:grid-cols-[1fr_180px_auto]"><input name="q" value="{{ request('q') }}" class="field" placeholder="Return no, invoice or supplier"><select name="status" class="field"><option value="">All status</option><option>Pending</option><option>Approved</option></select><button class="btn-secondary">Filter</button></form><div class="table-wrap"><table class="data-table min-w-[1050px]"><thead><tr><th>Return No</th><th>Purchase</th><th>Supplier</th><th>Product</th><th>Qty</th><th>Value</th><th>Refund Type</th><th>Status</th><th>Date</th><th>Actions</th></tr></thead><tbody>@forelse($returns as $return)<tr><td class="font-black text-red-600">{{ $return->number }}</td><td>{{ $return->purchase->invoice_number }}</td><td>{{ $return->supplier->name }}</td><td>{{ $return->item->product->name }}</td><td>{{ number_format($return->quantity,2) }}</td><td>Rs. {{ number_format($return->return_value,2) }}</td><td>{{ $return->refund_type }}</td><td><span class="rounded-full px-3 py-1 text-xs font-bold {{ $return->status==='Approved'?'bg-emerald-50 text-emerald-700':'bg-orange-50 text-orange-700' }}">{{ $return->status }}</span></td><td>{{ $return->return_date->format('d M Y') }}</td><td>@if($return->status==='Pending')<form method="POST" action="{{ route('purchases.returns.approve',$return) }}">@csrf<x-submission-token/><button class="btn-primary !px-3 !py-2" data-confirm="Approve this return and reduce stock?">Approve</button></form>@else<span class="text-xs text-slate-400">Processed</span>@endif</td></tr>@empty<tr><td colspan="10" class="py-12 text-center text-slate-400">Submitted purchase returns will appear here for approval.</td></tr>@endforelse</tbody></table><div class="border-t p-4">{{ $returns->links() }}</div></div></div></div>
<script>(()=>{const form=document.getElementById('return-form');const purchases={{ Illuminate\Support\Js::from($purchaseData) }};const purchase=form.querySelector('[data-purchase]');const item=form.querySelector('[data-item]');const sync=()=>{const record=purchases.find(p=>p.id==purchase.value);form.querySelector('[data-supplier]').textContent=record?.supplier||'—';form.querySelector('[data-store]').textContent=record?.store||'—';item.innerHTML='<option value="">Select product from purchase</option>'+((record?.items||[]).map(i=>`<option value="${i.id}">${i.label}</option>`).join(''))};purchase.addEventListener('change',sync);const refund=form.querySelector('[data-refund]');refund.addEventListener('change',()=>form.querySelector('[data-account]').classList.toggle('hidden',refund.value!=='Cash refund'));sync();})();</script></div></x-layouts::app>
